"use strict";
import { useQueryClient } from "@tanstack/react-query";
import { ProtocolVersion } from "@uniswap/client-pools/dist/pools/v1/types_pb";
import { popupRegistry } from "components/Popups/registry";
import { PopupType } from "components/Popups/types";
import { useAvailableGauges } from "hooks/useGaugeData";
import { useGaugeStaking } from "hooks/useGaugeStaking";
import { useMemo, useState } from "react";
import { useTranslation } from "react-i18next";
import styled from "styled-components";
import { Flex, Separator, SpinningLoader, Text, useSporeColors } from "ui/src";
import { CheckCircleFilled } from "ui/src/components/icons/CheckCircleFilled";
import { MinusCircle } from "ui/src/components/icons/MinusCircle";
const StyledButton = styled.button`
  all: unset;
  padding: 12px 16px;
  background-color: ${({ theme }) => theme.surface2};
  border-radius: 12px;
  border: 1px solid ${({ theme }) => theme.surface3};
  transition: all 0.2s ease;
  cursor: pointer;
  display: flex;
  justify-content: center;
  align-items: center;
  min-width: 120px;

  &:hover:not(:disabled) {
    background-color: ${({ theme }) => theme.surface2Hovered};
  }

  &:disabled {
    opacity: 0.5;
    cursor: not-allowed;
  }
`;
export function StakingSection({ position }) {
  const { t } = useTranslation();
  const colors = useSporeColors();
  const { data: gauges } = useAvailableGauges();
  const queryClient = useQueryClient();
  const [isStaking, setIsStaking] = useState(false);
  const [isUnstaking, setIsUnstaking] = useState(false);
  const [isClaimingRewards, setIsClaimingRewards] = useState(false);
  const hasGauge = useMemo(() => {
    if (!gauges || !position.poolId) return false;
    return gauges.some((gauge) => gauge.pool.toLowerCase() === position.poolId?.toLowerCase());
  }, [gauges, position.poolId]);
  const gaugeData = useGaugeStaking(position);
  if (!hasGauge) {
    return null;
  }
  const isStaked = gaugeData.isStaked;
  const stakedAmount0 = gaugeData.stakedAmount0 || "0.0000";
  const stakedAmount1 = gaugeData.stakedAmount1 || "0.0000";
  const unstakedAmount0 = gaugeData.unstakedAmount0 || "0.0000";
  const unstakedAmount1 = gaugeData.unstakedAmount1 || "0.0000";
  const handleStake = async () => {
    if (!gaugeData.canStake || isStaking) return;
    const positionIdForDisplay = position.tokenId || (position.version === ProtocolVersion.V2 ? "V2 LP" : "Unknown");
    const tokenPair = `${position.currency0Amount?.currency.symbol}-${position.currency1Amount?.currency.symbol}`;
    setIsStaking(true);
    try {
      const hash = await gaugeData.stakePosition(position.tokenId || "");
      popupRegistry.addPopup(
        {
          type: PopupType.LiquiditySuccess,
          content: {
            type: "success",
            title: "Position Staked",
            description: `Successfully staked ${tokenPair} position in gauge`
          }
        },
        `stake-success-${positionIdForDisplay}`
      );
      await queryClient.invalidateQueries({
        queryKey: ["abstract-position-orchestrated"]
      });
    } catch (error) {
      console.error("Failed to stake position:", error);
      popupRegistry.addPopup(
        {
          type: PopupType.StakeError,
          content: {
            type: "error",
            title: "Failed to Stake Position",
            description: error instanceof Error ? error.message : "An unexpected error occurred while staking your position.",
            action: "stake",
            positionId: positionIdForDisplay
          }
        },
        `stake-error-${positionIdForDisplay}`
      );
    } finally {
      setIsStaking(false);
    }
  };
  const handleUnstake = async () => {
    if (!gaugeData.isStaked || isUnstaking) return;
    const positionIdForDisplay = position.tokenId || (position.version === ProtocolVersion.V2 ? "V2 LP" : "Unknown");
    const tokenPair = `${position.currency0Amount?.currency.symbol}-${position.currency1Amount?.currency.symbol}`;
    setIsUnstaking(true);
    try {
      const hash = await gaugeData.unstakePosition(position.tokenId || "");
      popupRegistry.addPopup(
        {
          type: PopupType.LiquiditySuccess,
          content: {
            type: "success",
            title: "Position Unstaked",
            description: `Successfully unstaked ${tokenPair} position from gauge`
          }
        },
        `unstake-success-${positionIdForDisplay}`
      );
      await queryClient.invalidateQueries({
        queryKey: ["abstract-position-orchestrated"]
      });
    } catch (error) {
      console.error("Failed to unstake position:", error);
      popupRegistry.addPopup(
        {
          type: PopupType.UnstakeError,
          content: {
            type: "error",
            title: "Failed to Withdraw Position",
            description: error instanceof Error ? error.message : "An unexpected error occurred while withdrawing your position.",
            action: "unstake",
            positionId: positionIdForDisplay
          }
        },
        `unstake-error-${positionIdForDisplay}`
      );
    } finally {
      setIsUnstaking(false);
    }
  };
  const handleClaimRewards = async () => {
    if (isClaimingRewards) return;
    const tokenIdOrEmpty = position.tokenId || "";
    const positionIdForDisplay = position.tokenId || (position.version === ProtocolVersion.V2 ? "V2 LP" : "Unknown");
    const tokenPair = `${position.currency0Amount?.currency.symbol}-${position.currency1Amount?.currency.symbol}`;
    const rewardAmount = `${parseFloat(gaugeData.pendingRewards).toFixed(4)} ABX`;
    setIsClaimingRewards(true);
    try {
      const hash = await gaugeData.claimRewards(tokenIdOrEmpty);
      popupRegistry.addPopup(
        {
          type: PopupType.LiquiditySuccess,
          content: {
            type: "success",
            title: "Rewards Claimed",
            description: `Successfully claimed ${rewardAmount} from ${tokenPair} gauge`
          }
        },
        `claim-success-${positionIdForDisplay}`
      );
      await queryClient.invalidateQueries({
        queryKey: ["abstract-position-orchestrated"]
      });
    } catch (error) {
      console.error("Failed to claim rewards:", error);
      popupRegistry.addPopup(
        {
          type: PopupType.ClaimRewardsError,
          content: {
            type: "error",
            title: "Failed to Claim Rewards",
            description: error instanceof Error ? error.message : "An unexpected error occurred while claiming your rewards.",
            action: "claimRewards"
          }
        },
        `claim-rewards-error-${positionIdForDisplay}`
      );
    } finally {
      setIsClaimingRewards(false);
    }
  };
  return <Flex
    flexDirection="column"
    gap={"$spacing20"}
    position={"relative"}
    p={"$spacing16"}
    $md={{ p: "$spacing12" }}
    borderRadius={"$rounded12"}
    borderWidth={1}
    borderColor={"$surface3"}
    group
  >
      <Flex
    $group-hover={{ opacity: 0 }}
    position="absolute"
    inset={0}
    borderRadius={"$rounded12"}
    height={"100%"}
    width={"100%"}
    transition="opacity 0.2s ease"
    style={{
      background: `linear-gradient(10deg, ${colors.surface1.variable} 0%, ${colors.slate.variable} 100%)`
    }}
  />
      {
    /* Header */
  }
      <Flex row alignItems="center" gap="$gap8">
        {isStaked ? <CheckCircleFilled size={20} color="$statusSuccess" /> : <MinusCircle size={20} color="$neutral2" />}
        <Text variant="subheading1" color={isStaked ? "$statusSuccess" : "$neutral1"}>
          {isStaked ? "Staked" : "Not Staked"}
        </Text>
      </Flex>

      {
    /* Staking Information */
  }
      <Flex
    $platform-web={{ display: "grid", gridTemplateColumns: "1fr 1fr 1fr" }}
    $md={{ flexDirection: "column" }}
    gap="$spacing16"
  >
        {
    /* Staked Amount */
  }
        <Flex
    backgroundColor={isStaked ? "$statusSuccess2" : "$surface1"}
    p="$spacing12"
    borderRadius="$rounded8"
    flexDirection="column"
    borderWidth={2}
    borderColor={isStaked ? "$statusSuccess" : "$surface2"}
    gap="$gap8"
  >
          <Text variant="buttonLabel3" color="$neutral2">
            Staked Amount
          </Text>
          <Flex flexDirection="column" gap="$gap4">
            <Text variant="body2">
              {stakedAmount0} {position.currency0Amount?.currency.symbol}
            </Text>
            <Text variant="body2">
              {stakedAmount1} {position.currency1Amount?.currency.symbol}
            </Text>
          </Flex>
        </Flex>

        {
    /* Available to Stake */
  }
        <Flex
    backgroundColor="$surface1"
    p="$spacing12"
    borderRadius="$rounded8"
    flexDirection="column"
    gap="$gap8"
    borderWidth={2}
    borderColor={"$surface2"}
  >
          <Text variant="buttonLabel3" color="$neutral2">
            Available to Stake
          </Text>
          <Flex flexDirection="column" gap="$gap4">
            <Text variant="body2">
              {unstakedAmount0} {position.currency0Amount?.currency.symbol}
            </Text>
            <Text variant="body2">
              {unstakedAmount1} {position.currency1Amount?.currency.symbol}
            </Text>
          </Flex>
        </Flex>

        {
    /* Rewards */
  }
        <Flex
    backgroundColor="$surface1"
    p="$spacing12"
    borderRadius="$rounded8"
    flexDirection="column"
    gap="$gap8"
    borderWidth={2}
    borderColor={"$surface2"}
  >
          <Text variant="buttonLabel3" color="$neutral2">
            Pending Rewards
          </Text>
          <Text variant="body2">{parseFloat(gaugeData.pendingRewards).toFixed(6)} ABX</Text>
          {gaugeData.apr !== "N/A" && <Text variant="body3" color="$neutral3">
              APR: {gaugeData.apr}
            </Text>}
        </Flex>
      </Flex>

      <Separator width="100%" borderColor="$surface3" />

      {
    /* Action Buttons */
  }
      <Flex row gap="$gap12" justifyContent="center" $md={{ flexDirection: "column" }}>
        <StyledButton
    onClick={handleStake}
    disabled={gaugeData.isLoading || isStaked || !gaugeData.canStake || isStaking}
  >
          <Flex row alignItems="center" gap="$gap8">
            {isStaking && <SpinningLoader size={16} />}
            <Text
    variant="buttonLabel3"
    color={gaugeData.canStake && !isStaked && !isStaking ? "$neutral1" : "$neutral3"}
  >
              {isStaking ? "Staking" : gaugeData.isLoading ? "Loading" : isStaked ? "Already Staked" : gaugeData.needsApproval ? "Approve & Stake" : gaugeData.canStake ? "Stake" : "No LP to Stake"}
            </Text>
          </Flex>
        </StyledButton>

        <StyledButton onClick={handleUnstake} disabled={gaugeData.isLoading || !isStaked || isUnstaking}>
          <Flex row alignItems="center" gap="$gap8">
            {isUnstaking && <SpinningLoader size={16} />}
            <Text variant="buttonLabel3" color={isStaked && !isUnstaking ? "$neutral1" : "$neutral3"}>
              {isUnstaking ? "Withdrawing" : gaugeData.isLoading ? "Loading" : isStaked ? "Unstake" : "Not Staked"}
            </Text>
          </Flex>
        </StyledButton>

        <StyledButton
    onClick={handleClaimRewards}
    disabled={gaugeData.isLoading || !isStaked || parseFloat(gaugeData.pendingRewards) <= 0 || isClaimingRewards}
  >
          <Flex row alignItems="center" gap="$gap4">
            {isClaimingRewards && <SpinningLoader size={16} />}
            <Text
    variant="buttonLabel3"
    color={isStaked && parseFloat(gaugeData.pendingRewards) > 0 && !isClaimingRewards ? "$neutral1" : "$neutral3"}
  >
              {isClaimingRewards ? "Claiming" : parseFloat(gaugeData.pendingRewards) > 0 ? "Claim Rewards" : "No Rewards"}
            </Text>
          </Flex>
        </StyledButton>
      </Flex>
    </Flex>;
}
